window.TTS_DATA=window.TTS_DATA||{};window.TTS_DATA[11]=[{"t": "h", "l": 0, "s": "Лекц 11. Хурдан задалсан арга, DC урсгал, горимын хязгаар", "h": "<b>Лекц 11. Хурдан задалсан арга, DC урсгал, горимын</b> <b>хязгаар</b>"}, {"t": "p", "s": "Багш: Тэнхимийн эрхлэгч, доктор (Ph.D), дэд профессор Ш.Гантөмөр · Хугацаа: 2 цаг", "h": "Багш: Тэнхимийн эрхлэгч, доктор (Ph.D), дэд профессор Ш.Гантөмөр · Хугацаа: 2 цаг"}, {"t": "p", "s": "Лекцийн зорилго. Ньютон-Рафсоны аргыг хялбарчилсан хурдан задалсан арга (FDLF) ба тогтмол гүйдлийн (DC) загварыг гаргах, тэдгээрийн таамаглал, нарийвчлал, хэрэглээ; DC загварын мэдрэмжийн коэффициент (PTDF, LODF) ба n−1 шинжилгээ; горимын хязгаар — дулааны, хүчдэлийн, статик тогтворжилтын хязгаар, P–V муруй, ачааллын нөөц. Стендийн 3 ба 5 зангилааны схем дээр тооцно.", "h": "<b>Лекцийн зорилго. </b>Ньютон-Рафсоны аргыг хялбарчилсан хурдан задалсан арга (FDLF) ба тогтмол гүйдлийн (DC) загварыг гаргах, тэдгээрийн таамаглал, нарийвчлал, хэрэглээ; DC загварын мэдрэмжийн коэффициент (PTDF, LODF) ба n−1 шинжилгээ; горимын хязгаар — дулааны, хүчдэлийн, статик тогтворжилтын хязгаар, P–V муруй, ачааллын нөөц. Стендийн 3 ба 5 зангилааны схем дээр тооцно.", "x": "obj"}, {"t": "p", "s": "Түлхүүр үг: P–θ ба Q–U задаргаа, B′ ба B″ матриц, хурдан задалсан арга, DC урсгал, PTDF, LODF, горимын хязгаар, P–V муруй, λmax, хүчдэлийн тогтворжилт, үргэлжлүүлэлтийн арга.", "h": "<b>Түлхүүр үг: </b>P–θ ба Q–U задаргаа, <b>B</b>′ ба <b>B</b>″ матриц, хурдан задалсан арга, DC урсгал, PTDF, LODF, горимын хязгаар, P–V муруй, λ<sub>max</sub>, хүчдэлийн тогтворжилт, үргэлжлүүлэлтийн арга.", "x": "obj"}, {"t": "h", "l": 1, "s": "1. P–θ ба Q–U задаргаа", "h": "<b>1. P–θ ба Q–U задаргаа</b>"}, {"t": "p", "s": "Лекц 10-т Якобианы H = ∂P/∂θ ба L = ∂Q/∂U блокууд N, M-ээс хэд дахин том болохыг харсан (Жишээ 10.4: 3 дахин, X/R = 3; 220 кВ ба түүнээс дээш шугамд X/R = 5– 15). Өөрөөр хэлбэл бодит чадал голчлон өнцгөөс, хуурмаг чадал голчлон хүчдэлийн модулиас хамаарна. N ≈ 0, M ≈ 0 гэж үзвэл Ньютон-Рафсоны систем хоёр бие даасан, хоёр дахин бага хэмжээтэй систем болон задарна:", "h": "Лекц 10-т Якобианы <b>H </b>= ∂<b>P</b>/∂θ ба <b>L </b>= ∂<b>Q</b>/∂<b>U </b>блокууд <b>N</b>, <b>M</b>-ээс хэд дахин том болохыг харсан (Жишээ 10.4: 3 дахин, X/R = 3; 220 кВ ба түүнээс дээш шугамд X/R = 5– 15). Өөрөөр хэлбэл бодит чадал голчлон өнцгөөс, хуурмаг чадал голчлон хүчдэлийн модулиас хамаарна. <b>N </b>≈ 0, <b>M </b>≈ 0 гэж үзвэл Ньютон-Рафсоны систем хоёр бие даасан, хоёр дахин бага хэмжээтэй систем болон задарна:"}, {"t": "eq", "s": "H·Δθ = ΔP ; L·ΔU = ΔQ (11.1)", "h": "<b>H</b>·Δθ = Δ<b>P </b>; <b>L</b>·Δ<b>U </b>= Δ<b>Q </b>(11.1)", "n": "11.1", "img": "data:image/png;base64,", "iw": 419}, {"t": "p", "s": "Энэ задалсан Ньютоны арга нь бүрэн Якобианы оронд хоёр жижиг матриц задлах тул тооцоог ~4 дахин хэмнэнэ, гэвч давталт бүрт H, L-г шинэчилсээр байна.", "h": "Энэ <b>задалсан Ньютоны арга </b>нь бүрэн Якобианы оронд хоёр жижиг матриц задлах тул тооцоог ~4 дахин хэмнэнэ, гэвч давталт бүрт <b>H</b>, <b>L</b>-г шинэчилсээр байна."}, {"t": "h", "l": 1, "s": "2. Хурдан задалсан арга (FDLF)", "h": "<b>2. Хурдан задалсан арга (FDLF)</b>"}, {"t": "p", "s": "Stott ба Alsac (1974) дараах нэмэлт таамаглалаар H, L-г тогтмол матрицаар солив:", "h": "Stott ба Alsac (1974) дараах нэмэлт таамаглалаар <b>H</b>, <b>L</b>-г <b>тогтмол </b>матрицаар солив:"}, {"t": "p", "s": "1. Шугамын хоёр үзүүрийн өнцгийн зөрүү бага: cosθij ≈ 1, Gijsinθij ≪ Bij.", "h": "1. Шугамын хоёр үзүүрийн өнцгийн зөрүү бага: cosθ<sub>ij</sub> ≈ 1, G<sub>ij</sub>sinθ<sub>ij</sub> ≪ B<sub>ij</sub>."}, {"t": "p", "s": "2. Qi ≪ BiiUi² (диагональ элементийн −Qi гишүүнийг тооцохгүй).", "h": "2. Q<sub>i</sub> ≪ B<sub>ii</sub>U<sub>i</sub>² (диагональ элементийн −Q<sub>i</sub> гишүүнийг тооцохгүй)."}, {"t": "p", "s": "3. Хүчдэлийг ΔP/U, ΔQ/U хэлбэрээр баруун талд шилжүүлж, зүүн талын Uj-г 1 гэж авна.", "h": "3. Хүчдэлийг ΔP/U, ΔQ/U хэлбэрээр баруун талд шилжүүлж, зүүн талын U<sub>j</sub>-г 1 гэж авна."}, {"t": "p", "s": "Тэгвэл Hij ≈ −UiUjBij, Lij ≈ −UiBij болж:", "h": "Тэгвэл H<sub>ij</sub> ≈ −U<sub>i</sub>U<sub>j</sub>B<sub>ij</sub>, L<sub>ij</sub> ≈ −U<sub>i</sub>B<sub>ij</sub> болж:"}, {"t": "eq", "s": "ΔP/U = B′·Δθ ; ΔQ/U = B″·ΔU (11.2)", "h": "Δ<b>P</b>/<b>U </b>= <b>B</b>′·Δθ ; Δ<b>Q</b>/<b>U </b>= <b>B</b>″·Δ<b>U </b>(11.2)", "n": "11.2", "img": "data:image/png;base64,", "iw": 439}, {"t": "p", "s": "B′ ба B″ — тогтмол, бодит, тэгш хэмт, сийрэг матрицууд; тооцооны эхэнд нэг удаа LDLᵀ задаргаа хийнэ (лекц 8). Нийлэлтийг сайжруулах үүднээс тэдгээрт өөр өөр элемент оруулдаг (XB хувилбар):", "h": "<b>B</b>′ ба <b>B</b>″ — тогтмол, бодит, тэгш хэмт, сийрэг матрицууд; тооцооны эхэнд <b>нэг удаа</b> LDLᵀ задаргаа хийнэ (лекц 8). Нийлэлтийг сайжруулах үүднээс тэдгээрт өөр өөр элемент оруулдаг (XB хувилбар):"}, {"t": "p", "s": "B′ (баланс зангилааг хассан, PV + PQ): салааны b = 1/xij (R-ийг тооцохгүй), хөндлөн салаа (B/2, шунт), трансформаторын нэрлэсэн бус k-г тооцохгүй — бодит чадалд нөлөө багатай элементүүдийг хасна.", "h": "<b>B</b>′ (баланс зангилааг хассан, PV + PQ): салааны b = 1/x<sub>ij</sub> (R-ийг тооцохгүй), хөндлөн салаа (B/2, шунт), трансформаторын нэрлэсэн бус k-г <b>тооцохгүй </b>— бодит чадалд нөлөө багатай элементүүдийг хасна."}, {"t": "p", "s": "B″ (зөвхөн PQ): B″ = −Im Y — бүх элемент (R, шунт, k) орно, учир нь эдгээр нь хуурмаг чадалд нөлөөтэй.", "h": "<b>B</b>″ (зөвхөн PQ): <b>B</b>″ = −Im <b>Y </b>— бүх элемент (R, шунт, k) орно, учир нь эдгээр нь хуурмаг чадалд нөлөөтэй."}, {"t": "p", "s": "Алгоритм — давталт бүр хоёр «хагас давталттай»: (1) ΔP-г тооцож B′Δθ = ΔP/U-ээс θ-г шинэчлэх; (2) шинэ θ-гаар ΔQ-г тооцож B″ΔU = ΔQ/U-ээс U-г шинэчлэх. Хоёр хагас давталтын аль алинд үлдэгдэл бага бол зогсоно. Хэдийгээр матриц ойролцоо боловч үлдэгдэл (ΔP, ΔQ) нарийн тооцогддог тул эцсийн шийдэл Ньютон-Рафсоных шиг нарийвчлалтай — зөвхөн давталтын тоо нэмэгдэнэ.", "h": "<b>Алгоритм </b>— давталт бүр хоёр «хагас давталттай»: (1) Δ<b>P</b>-г тооцож <b>B</b>′Δθ = Δ<b>P</b>/<b>U</b>-ээс θ-г шинэчлэх; (2) шинэ θ-гаар Δ<b>Q</b>-г тооцож <b>B</b>″Δ<b>U </b>= Δ<b>Q</b>/<b>U</b>-ээс <b>U</b>-г шинэчлэх. Хоёр хагас давталтын аль алинд үлдэгдэл бага бол зогсоно. Хэдийгээр матриц ойролцоо боловч <b>үлдэгдэл (ΔP, ΔQ) нарийн тооцогддог </b>тул эцсийн шийдэл Ньютон-Рафсоных шиг нарийвчлалтай — зөвхөн давталтын тоо нэмэгдэнэ."}, {"t": "p", "s": "Жишээ 11.1. Стендийн 3 зангилааны схем. x12 = 0.04, x13 = 0.03, x23 = 0.025 → 1/x: 25, 33.333, 40. Бүтэн B′ ба баланс зангилааг хассан хэсэг:", "h": "<b>Жишээ 11.1. Стендийн 3 зангилааны схем. </b>x<sub>12</sub> = 0.04, x<sub>13</sub> = 0.03, x<sub>23</sub> = 0.025 → 1/x: 25, 33.333, 40. Бүтэн <b>B</b>′ ба баланс зангилааг хассан хэсэг:", "x": "ex"}, {"t": "p", "s": "58.333 −25 −33.333", "h": "58.333 −25 −33.333", "x": "ex"}, {"t": "p", "s": "65 −40", "h": "65 −40", "x": "ex"}, {"t": "eq", "s": "B′бүтэн = −25 65 −40 ; B′ = ; B″ = [−B22] = [52] (11.3)", "h": "<b>B</b>′<sub>бүтэн</sub> = −25 65 −40 ; <b>B</b>′ = ; <b>B</b>″ = [−B<sub>22</sub>] = [52] (11.3)", "n": "11.3", "img": "data:image/png;base64,", "iw": 589}, {"t": "p", "s": "−40 73.333 −33.333 −40 73.333", "h": "−40 73.333 −33.333 −40 73.333", "x": "ex"}, {"t": "p", "s": "Анхаар: B′ (1/x, R-гүй) ба B″ (−Im Y, R-тэй: −Im(1/(0.02 + j0.04)) = 20 ≠ 25) ялгаатай. Давталт 1, P-хагас. Хавтгай эхлэлд ΔP2 = −2.860, ΔP3 = 1.438 (лекц 10); ΔP/U = [−2.860/1; 1.438/1.04] = [−2.860; 1.383]. B′Δθ = ΔP/U-ээс Δθ = [−0.04877; −0.00773] рад = [−2.794°; −0.443°].", "h": "Анхаар: <b>B</b>′ (1/x, R-гүй) ба <b>B</b>″ (−Im <b>Y</b>, R-тэй: −Im(1/(0.02 + j0.04)) = 20 ≠ 25) ялгаатай. <b>Давталт 1, P-хагас. </b>Хавтгай эхлэлд ΔP<sub>2</sub> = −2.860, ΔP<sub>3</sub> = 1.438 (лекц 10); Δ<b>P</b>/<b>U </b>= [−2.860/1; 1.438/1.04] = [−2.860; 1.383]. <b>B</b>′Δθ = Δ<b>P</b>/<b>U</b>-ээс Δθ = [−0.04877; −0.00773] рад = [−2.794°; −0.443°].", "x": "ex"}, {"t": "p", "s": "Давталт 1, Q-хагас. Шинэ өнцгөөр Q2 = −1.033, ΔQ2 = −2.5 + 1.033 = −1.467; ΔU2 = (−1.467/1.0)/52 = −0.02822 → U2 = 0.97178. Ньютон-Рафсоны эхний давталттай (θ2 = −2.593°, U2 = 0.97345) ойролцоо — хоёр жижиг тогтмол систем бүрэн Якобиантай бараг ижил засвар өгсөн.", "h": "<b>Давталт 1, Q-хагас. </b>Шинэ өнцгөөр Q<sub>2</sub> = −1.033, ΔQ<sub>2</sub> = −2.5 + 1.033 = −1.467; ΔU<sub>2</sub> = (−1.467/1.0)/52 = −0.02822 → U<sub>2</sub> = 0.97178. Ньютон-Рафсоны эхний давталттай (θ<sub>2</sub> = −2.593°, U<sub>2</sub> = 0.97345) ойролцоо — хоёр жижиг тогтмол систем бүрэн Якобиантай бараг ижил засвар өгсөн.", "x": "ex"}, {"t": "tbl", "s": "", "head": ["k", "U 2", "θ , ° 2", "θ , ° 3", "max|Δ|"], "rows": [["1", "0.97178", "−2.794", "−0.443", "1.2·10⁻¹"], ["2", "0.97143", "−2.717", "−0.490", "2.9·10⁻²"], ["3", "0.97167", "−2.696", "−0.498", "9.9·10⁻⁴"], ["4", "0.97168", "−2.696", "−0.499", "2.6·10⁻⁴"], ["5", "0.97168", "−2.696", "−0.499", "1.4·10⁻⁵"], ["6", "0.97168", "−2.696", "−0.499", "1.8·10⁻⁶"]]}, {"t": "cap", "s": "Хүснэгт 11.1. Хурдан задалсан аргын давталт (3 зангилаа)", "h": "Хүснэгт 11.1. Хурдан задалсан аргын давталт (3 зангилаа)"}, {"t": "p", "s": "6 давталтаар 10⁻⁵-аас бага болж Ньютон-Рафсоны шийдэлтэй ижил үр дүнд хүрэв. Нийлэлт шугаман (алдаа давталт бүрт 4–20 дахин буурна). Энэ схемийн R/X = 0.5 харьцангуй их тул FDLF-ийн хувьд «хүнд» тохиолдол.", "h": "6 давталтаар 10⁻⁵-аас бага болж Ньютон-Рафсоны шийдэлтэй ижил үр дүнд хүрэв. Нийлэлт шугаман (алдаа давталт бүрт 4–20 дахин буурна). Энэ схемийн R/X = 0.5 харьцангуй их тул FDLF-ийн хувьд «хүнд» тохиолдол.", "x": "ex"}, {"t": "p", "s": "Жишээ 11.2. 5 зангилааны схем. B′ нь лекц 8-ын (8.1)-ийн матрицтай ижил (1/x). B″ = −Im Y ((7.10)-аас, бүх зангилаа PQ):", "h": "<b>Жишээ 11.2. 5 зангилааны схем. B</b>′ нь лекц 8-ын (8.1)-ийн матрицтай ижил (1/x). <b>B</b>″ = −Im <b>Y </b>((7.10)-аас, бүх зангилаа PQ):", "x": "ex"}, {"t": "p", "s": "32.415 −5.000 −5.000 −7.500 −5.000 38.695 −30.000 0", "h": "32.415 −5.000 −5.000 −7.500 −5.000 38.695 −30.000 0", "x": "ex"}, {"t": "eq", "s": "B″ = (11.6)", "h": "<b>B</b>″ = (11.6)", "n": "11.6", "img": "data:image/png;base64,", "iw": 468}, {"t": "p", "s": "−5.000 −30.000 38.695 −3.750 −7.500 0 −3.750 11.210", "h": "−5.000 −30.000 38.695 −3.750 −7.500 0 −3.750 11.210", "x": "ex"}, {"t": "p", "s": "B″-ийн диагональд шугамын B/2 багтаамж орсон тул B′-ийнхээс бага (32.415 < 36.111). Давталт:", "h": "<b>B</b>″-ийн диагональд шугамын B/2 багтаамж орсон тул <b>B</b>′-ийнхээс бага (32.415 &lt; 36.111). Давталт:", "x": "ex"}, {"t": "tbl", "s": "", "head": ["k", "U 2", "U 5", "θ , ° 2", "θ , ° 5", "max|Δ|"], "rows": [["1", "1.0538", "1.0227", "−1.905", "−5.599", "4.2·10⁻¹"], ["2", "1.0472", "1.0179", "−2.849", "−6.153", "2.7·10⁻²"], ["3", "1.0475", "1.0179", "−2.805", "−6.150", "1.2·10⁻³"], ["4", "1.0474", "1.0179", "−2.806", "−6.150", "6.3·10⁻⁵"], ["5", "1.0474", "1.0179", "−2.806", "−6.150", "3.8·10⁻⁶"]]}, {"t": "cap", "s": "Хүснэгт 11.2. Хурдан задалсан аргын давталт (5 зангилаа)", "h": "Хүснэгт 11.2. Хурдан задалсан аргын давталт (5 зангилаа)"}, {"t": "p", "s": "Алдаа давталт бүрт 15–20 дахин буурч (шугаман нийлэлт), 5 давталтаар Хүснэгт 9.4-ийн шийдэлд хүрэв. IEEE 14 схем мөн 5 давталтаар (4.7·10⁻¹ → 1.9·10⁻² → 8.9·10⁻⁴ → 4.8·10⁻⁵ → 4.1·10⁻⁶) нийлэв.", "h": "Алдаа давталт бүрт 15–20 дахин буурч (шугаман нийлэлт), 5 давталтаар Хүснэгт 9.4-ийн шийдэлд хүрэв. IEEE 14 схем мөн 5 давталтаар (4.7·10⁻¹ → 1.9·10⁻² → 8.9·10⁻⁴ → 4.8·10⁻⁵ → 4.1·10⁻⁶) нийлэв.", "x": "ex"}, {"t": "h", "l": 2, "s": "Хувилбарууд ба PV зангилаа", "h": "<b>Хувилбарууд ба PV зангилаа</b>"}, {"t": "p", "s": "XB ба BX хувилбар. Дээр тайлбарласан нь Stott-Alsac-ийн анхны XB хувилбар (B′-д 1/x, B″-д −Im Y). vanAmerongen (1989) ба Monticelli (1990) нар эсрэгээр нь B′-д −Im Y-ийн салааны хэсэг, B″-д 1/x-ийг авсан BX хувилбар нь R/X их сүлжээнд илүү найдвартай нийлдэгийг харуулсан. MATPOWER зэрэг програм хоёуланг нь санал болгодог. Стендийн 3 зангилааны схемд B′-ийн оронд −Im Y-г бүхэлд нь хэрэглэхэд давталт 6-аас 9 болж өссөн нь матрицын сонголтын ач холбогдлыг харуулна.", "h": "<b>XB ба BX хувилбар. </b>Дээр тайлбарласан нь Stott-Alsac-ийн анхны <b>XB </b>хувилбар (<b>B</b>′-д 1/x, <b>B</b>″-д −Im <b>Y</b>). vanAmerongen (1989) ба Monticelli (1990) нар эсрэгээр нь <b>B</b>′-д −Im <b>Y</b>-ийн салааны хэсэг, <b>B</b>″-д 1/x-ийг авсан <b>BX </b>хувилбар нь R/X их сүлжээнд илүү найдвартай нийлдэгийг харуулсан. MATPOWER зэрэг програм хоёуланг нь санал болгодог. Стендийн 3 зангилааны схемд <b>B</b>′-ийн оронд −Im <b>Y</b>-г бүхэлд нь хэрэглэхэд давталт 6-аас 9 болж өссөн нь матрицын сонголтын ач холбогдлыг харуулна."}, {"t": "p", "s": "PV зангилаа. PV зангилааны хүчдэл тогтмол тул B″-д түүний мөр, багана ордоггүй; B′-д орно. Хуурмаг чадлын хязгаар зөрчигдвөл зангилаа PQ болж B″-ийн хэмжээ нэгээр өснө — тогтмол матрицыг дахин задлах шаардлагатай; үүнийг хэмнэхийн тулд B″-ийг бүх PV зангилааг оруулан урьдчилан задалж, PV зангилааны мөрийг «идэвхгүй» болгох арга хэрэглэдэг. Трансформаторын коэффициент өөрчлөгдөхөд мөн B″ өөрчлөгдөнө.", "h": "<b>PV зангилаа. </b>PV зангилааны хүчдэл тогтмол тул <b>B</b>″-д түүний мөр, багана ордоггүй; <b>B</b>′-д орно. Хуурмаг чадлын хязгаар зөрчигдвөл зангилаа PQ болж <b>B</b>″-ийн хэмжээ нэгээр өснө — тогтмол матрицыг дахин задлах шаардлагатай; үүнийг хэмнэхийн тулд <b>B</b>″-ийг бүх PV зангилааг оруулан урьдчилан задалж, PV зангилааны мөрийг «идэвхгүй» болгох арга хэрэглэдэг. Трансформаторын коэффициент өөрчлөгдөхөд мөн <b>B</b>″ өөрчлөгдөнө."}, {"t": "h", "l": 1, "s": "3. Аргуудын нарийвчлал ба хурдыг харьцуулах", "h": "<b>3. Аргуудын нарийвчлал ба хурдыг харьцуулах</b>"}, {"t": "tbl", "s": "", "head": ["Схем", "Гаусс-Зейдель (α = 1)", "Ньютон-Рафсон", "«Хуурамч» Ньютон", "Хурдан задалсан"], "rows": [["3 зангилаа", "9", "3", "5", "5–6"], ["5 зангилаа", "33", "3", "7", "5"], ["IEEE 14", "106", "3", "7", "5"]]}, {"t": "cap", "s": "Хүснэгт 11.3. Давталтын тоо (ε = 10⁻⁵)", "h": "Хүснэгт 11.3. Давталтын тоо (ε = 10⁻⁵)"}, {"t": "p", "s": "Хурдан задалсан аргын нэг давталт нь Ньютон-Рафсоных шиг Якобиан байгуулж задлах шаардлагагүй, зөвхөн хоёр удаа (B′, B″) орлуулалт хийх тул 5–10 дахин хямд. Иймд давталтын тоо 2 дахин их ч нийт хугацаа 3–5 дахин бага. Энэ давуу тал n−1 шинжилгээ (олон мянган хувилбар), бодит цагийн диспетчерийн системд (SCADA/EMS) шийдвэрлэх ач холбогдолтой.", "h": "Хурдан задалсан аргын нэг давталт нь Ньютон-Рафсоных шиг Якобиан байгуулж задлах шаардлагагүй, зөвхөн хоёр удаа (<b>B</b>′, <b>B</b>″) орлуулалт хийх тул 5–10 дахин хямд. Иймд давталтын тоо 2 дахин их ч нийт хугацаа 3–5 дахин бага. Энэ давуу тал n−1 шинжилгээ (олон мянган хувилбар), бодит цагийн диспетчерийн системд (SCADA/EMS) шийдвэрлэх ач холбогдолтой."}, {"t": "p", "s": "R/X-ийн нөлөө. 5 зангилааны схемийн бүх R-ийг үржүүлж туршсан:", "h": "<b>R/X-ийн нөлөө. </b>5 зангилааны схемийн бүх R-ийг үржүүлж туршсан:"}, {"t": "tbl", "s": "", "head": ["R/X", "0.17", "0.33", "0.67", "1.0", "1.33"], "rows": [["FDLF давталт", "5", "5", "6", "8", "9"], ["Ньютон-Рафсон", "3", "3", "3", "3", "3"]]}, {"t": "cap", "s": "Хүснэгт 11.4. R/X харьцааны нөлөө (5 зангилаа)", "h": "Хүснэгт 11.4. R/X харьцааны нөлөө (5 зангилаа)"}, {"t": "p", "s": "R/X өсөхөд задаргааны таамаглал муудаж FDLF удаашрах бол Ньютон-Рафсонд нөлөөгүй. Түгээх сүлжээнд (R/X = 1–5) FDLF муу ажиллах эсвэл задрах тул урвуу-шууд гүйлтийн арга (лекц 5) эсвэл Ньютон-Рафсон хэрэглэнэ.", "h": "R/X өсөхөд задаргааны таамаглал муудаж FDLF удаашрах бол Ньютон-Рафсонд нөлөөгүй. Түгээх сүлжээнд (R/X = 1–5) FDLF муу ажиллах эсвэл задрах тул урвуу-шууд гүйлтийн арга (лекц 5) эсвэл Ньютон-Рафсон хэрэглэнэ."}, {"t": "h", "l": 1, "s": "4. DC (тогтмол гүйдлийн) загвар", "h": "<b>4. DC (тогтмол гүйдлийн) загвар</b>"}, {"t": "p", "s": "Хурдан задалсан аргыг цааш хялбарчилж: (1) бүх хүчдэл Ui = 1 о.н.; (2) R = 0 (алдагдалгүй); (3) sinθij ≈ θij гэвэл Q-ийн тэгшитгэл орхигдож, бодит чадлын тэгшитгэл шугаман болно:", "h": "Хурдан задалсан аргыг цааш хялбарчилж: (1) бүх хүчдэл U<sub>i</sub> = 1 о.н.; (2) R = 0 (алдагдалгүй); (3) sinθ<sub>ij</sub> ≈ θ<sub>ij</sub> гэвэл <b>Q</b>-ийн тэгшитгэл орхигдож, бодит чадлын тэгшитгэл <b>шугаман </b>болно:"}, {"t": "eq", "s": "Pij = (θi − θj)/xij ; P = B′·θ ⇒θ = B′⁻¹P = X·P (11.4)", "h": "P<sub>ij</sub> = (θ<sub>i</sub> − θ<sub>j</sub>)/x<sub>ij</sub> ; <b>P </b>= <b>B</b>′·θ ⇒θ = <b>B</b>′⁻¹<b>P </b>= <b>X</b>·<b>P </b>(11.4)", "n": "11.4", "img": "data:image/png;base64,", "iw": 491}, {"t": "p", "s": "Нэр нь тогтмол гүйдлийн хэлхээтэй (гүйдэл ↔ P, хүчдэл ↔ θ, эсэргүүцэл ↔ x) аналог байгаагаас гарсан. Давталтгүй, нэг шугаман систем; шийдэл үргэлж оршин байна, хурдан. Хэрэглээ: цахилгаан эрчим хүчний зах зээл (зангилааны үнэ), n−1 шинжилгээний урьдчилсан шүүлт, хөгжлийн төлөвлөлт (олон мянган хувилбар), оновчлол (DC-OPF).", "h": "Нэр нь тогтмол гүйдлийн хэлхээтэй (гүйдэл ↔ P, хүчдэл ↔ θ, эсэргүүцэл ↔ x) аналог байгаагаас гарсан. Давталтгүй, нэг шугаман систем; шийдэл үргэлж оршин байна, хурдан. <b>Хэрэглээ: </b>цахилгаан эрчим хүчний зах зээл (зангилааны үнэ), n−1 шинжилгээний урьдчилсан шүүлт, хөгжлийн төлөвлөлт (олон мянган хувилбар), оновчлол (DC-OPF)."}, {"t": "p", "s": "Жишээ 11.3. DC ба AC загварыг харьцуулах (стендийн 5 зангилаа; DC — лекц 8,", "h": "<b>Жишээ 11.3. DC ба AC загварыг харьцуулах </b>(стендийн 5 зангилаа; DC — лекц 8,", "x": "ex"}, {"t": "p", "s": "Жишээ 8.1; AC — лекц 9, Хүснэгт 9.5):", "h": "Жишээ 8.1; AC — лекц 9, Хүснэгт 9.5):", "x": "ex"}, {"t": "tbl", "s": "", "head": ["Салаа", "1–2", "1–3", "2–3", "2–4", "2–5", "3–4", "4–5"], "rows": [["DC, МВт", "85.4", "39.6", "24.3", "27.4", "53.7", "18.9", "6.3"], ["AC (эхлэлд), МВт", "88.9", "40.7", "24.7", "27.9", "54.8", "18.9", "6.3"], ["Алдаа, %", "−3.9", "−2.8", "−1.7", "−1.8", "−2.0", "0", "0"]]}, {"t": "cap", "s": "Хүснэгт 11.5. DC ба AC урсгал", "h": "Хүснэгт 11.5. DC ба AC урсгал"}, {"t": "p", "s": "DC загвар бодит чадлын урсгалыг 0–4 % алдаатай өгсөн; системийн алдагдал (4.59 МВт) тооцогдоогүй тул баланс зангилааны чадал 125 МВт (AC: 129.6). Хүчдэл ба хуурмаг чадлын талаар DC загвар мэдээлэлгүй — хүчдэлийн асуудалтай горимд хэрэглэх боломжгүй.", "h": "DC загвар бодит чадлын урсгалыг 0–4 % алдаатай өгсөн; системийн алдагдал (4.59 МВт) тооцогдоогүй тул баланс зангилааны чадал 125 МВт (AC: 129.6). Хүчдэл ба хуурмаг чадлын талаар DC загвар мэдээлэлгүй — хүчдэлийн асуудалтай горимд хэрэглэх боломжгүй.", "x": "ex"}, {"t": "h", "l": 2, "s": "Алдагдлыг DC загварт тооцох", "h": "<b>Алдагдлыг DC загварт тооцох</b>"}, {"t": "p", "s": "DC урсгалаар салааны бодит чадлын алдагдлыг ойролцоогоор ΔPij ≈ rijPij² (U = 1, хуурмаг урсгалыг тооцохгүй) гэж үнэлж болно. 5 зангилааны схемд: 1–2: 1.46; 1–3: 1.26; 2– 3: 0.35; 2–4: 0.45; 2–5: 1.15; 3–4: 0.04; 4–5: 0.03 МВт, нийт 4.74 МВт (AC: 4.59 МВт, Хүснэгт 9.5) — 3 %-ийн алдаатай. Энэ алдагдлыг хагасаар нь салааны хоёр үзүүрийн зангилаанд нэмэлт ачаалал болгон хуваарилж DC тооцоог давтвал («алдагдалтай DC») баланс зангилааны чадал AC-тэй ойртоно. Ийм загварыг зах зээлийн тооцоонд өргөн хэрэглэдэг.", "h": "DC урсгалаар салааны бодит чадлын алдагдлыг ойролцоогоор ΔP<sub>ij</sub> ≈ r<sub>ij</sub>P<sub>ij</sub>² (U = 1, хуурмаг урсгалыг тооцохгүй) гэж үнэлж болно. 5 зангилааны схемд: 1–2: 1.46; 1–3: 1.26; 2– 3: 0.35; 2–4: 0.45; 2–5: 1.15; 3–4: 0.04; 4–5: 0.03 МВт, нийт <b>4.74 МВт </b>(AC: 4.59 МВт, Хүснэгт 9.5) — 3 %-ийн алдаатай. Энэ алдагдлыг хагасаар нь салааны хоёр үзүүрийн зангилаанд нэмэлт ачаалал болгон хуваарилж DC тооцоог давтвал («алдагдалтай DC») баланс зангилааны чадал AC-тэй ойртоно. Ийм загварыг зах зээлийн тооцоонд өргөн хэрэглэдэг."}, {"t": "h", "l": 2, "s": "Зах зээлийн хэрэглээ: зангилааны үнэ", "h": "<b>Зах зээлийн хэрэглээ: зангилааны үнэ</b>"}, {"t": "p", "s": "Цахилгаан эрчим хүчний бөөний зах зээлтэй орнуудад (АНУ-ын PJM, Европ) генераторуудын ачааллыг DC загвар дээр суурилсан оновчлол (DC-OPF)-оор хуваарилдаг: нийт зардлыг хамгийн бага болгох, шугамын хязгаарыг (PTDF-ээр илэрхийлсэн шугаман нөхцөл) хангах. Шугам хязгаартаа хүрэх (түгжрэл) үед зангилаа бүрийн эрчим хүчний үнэ өөр болдог — зангилааны ахиу үнэ (LMP). Үүний хэсэг нь PTDF·(шугамын хязгаарын «сүүдрийн үнэ»). Ийнхүү DC загвар ба PTDF нь техникийн тооцооноос гадна эдийн засгийн шийдвэрийн суурь болдог. Горимыг оновчлох асуудлыг «Эрчим хүчний системийн горимын оновчлол» (Ш.Гантөмөр, Ч.Зундуйсүрэн, 2001) номд дэлгэрэнгүй авч үзсэн.", "h": "Цахилгаан эрчим хүчний бөөний зах зээлтэй орнуудад (АНУ-ын PJM, Европ) генераторуудын ачааллыг <b>DC загвар дээр суурилсан оновчлол </b>(DC-OPF)-оор хуваарилдаг: нийт зардлыг хамгийн бага болгох, шугамын хязгаарыг (PTDF-ээр илэрхийлсэн шугаман нөхцөл) хангах. Шугам хязгаартаа хүрэх (түгжрэл) үед зангилаа бүрийн эрчим хүчний үнэ өөр болдог — <b>зангилааны ахиу үнэ </b>(LMP). Үүний хэсэг нь PTDF·(шугамын хязгаарын «сүүдрийн үнэ»). Ийнхүү DC загвар ба PTDF нь техникийн тооцооноос гадна эдийн засгийн шийдвэрийн суурь болдог. Горимыг оновчлох асуудлыг «Эрчим хүчний системийн горимын оновчлол» (Ш.Гантөмөр, Ч.Зундуйсүрэн, 2001) номд дэлгэрэнгүй авч үзсэн."}, {"t": "h", "l": 1, "s": "5. Мэдрэмжийн коэффициент: PTDF ба LODF", "h": "<b>5. Мэдрэмжийн коэффициент: PTDF ба LODF</b>"}, {"t": "p", "s": "DC загвар шугаман тул суперпозиц хэрэглэж болно. PTDF (Power Transfer Distribution Factor) — k зангилаанд 1 о.н. тарьж баланс зангилаанаас авахад i–j салааны урсгалын өөрчлөлт:", "h": "DC загвар шугаман тул суперпозиц хэрэглэж болно. <b>PTDF </b>(Power Transfer Distribution Factor) — k зангилаанд 1 о.н. тарьж баланс зангилаанаас авахад i–j салааны урсгалын өөрчлөлт:"}, {"t": "eq", "s": "PTDFij,k = (Xik − Xjk)/xij ; LODFij,mn = PTDFij,(m→n)/(1 − PTDFmn,(m→n)) (11.5)", "h": "PTDF<sub>ij,k</sub> = (X<sub>ik</sub> − X<sub>jk</sub>)/x<sub>ij</sub> ; LODF<sub>ij,mn</sub> = PTDF<sub>ij,(m→n)</sub>/(1 − PTDF<sub>mn,(m→n)</sub>) (11.5)", "n": "11.5", "img": "data:image/png;base64,", "iw": 584}, {"t": "p", "s": "X = B′⁻¹ (баланс зангилааны мөр, багана тэг). LODF (Line Outage Distribution Factor) — m–n салаа тасрахад түүний өмнөх урсгалын ямар хэсэг i–j салаанд шилжихийг заана:", "h": "<b>X </b>= <b>B</b>′⁻¹ (баланс зангилааны мөр, багана тэг). <b>LODF </b>(Line Outage Distribution Factor) — m–n салаа тасрахад түүний өмнөх урсгалын ямар хэсэг i–j салаанд шилжихийг заана:"}, {"t": "p", "s": "P′ij = Pij + LODFij,mn·Pmn. Энэ нь n−1 шинжилгээг давталтгүй, нэг үржвэрээр гүйцэтгэх боломж олгоно.", "h": "P′<sub>ij</sub> = P<sub>ij</sub> + LODF<sub>ij,mn</sub>·P<sub>mn</sub>. Энэ нь n−1 шинжилгээг давталтгүй, нэг үржвэрээр гүйцэтгэх боломж олгоно."}, {"t": "p", "s": "Жишээ 11.4. 5 зангилааны схемийн PTDF (баланс — 1):", "h": "<b>Жишээ 11.4. </b>5 зангилааны схемийн PTDF (баланс — 1):", "x": "ex"}, {"t": "tbl", "s": "", "head": ["Салаа", "k = 2", "k = 3", "k = 4", "k = 5"], "rows": [["1–2", "−0.843", "−0.629", "−0.671", "−0.786"], ["1–3", "−0.157", "−0.371", "−0.329", "−0.214"], ["2–3", "0.071", "−0.286", "−0.214", "−0.024"], ["2–4", "0.057", "−0.229", "−0.305", "−0.063"], ["2–5", "0.029", "−0.114", "−0.152", "−0.698"], ["3–4", "−0.086", "0.343", "−0.543", "−0.238"], ["4–5", "−0.029", "0.114", "0.152", "−0.302"]]}, {"t": "cap", "s": "Хүснэгт 11.6. PTDF матриц", "h": "Хүснэгт 11.6. PTDF матриц"}, {"t": "p", "s": "Тайлбар: 5-р зангилааны ачааллыг 10 МВт нэмэгдүүлбэл (k = 5-д −0.1 о.н. тарилт) 1–2 шугамын урсгал 0.786·10 = 7.9 МВт, 2–5 шугамынх 7.0 МВт өснө. Багана бүрийн 1–2 ба 1–3 мөрийн нийлбэр −1 — тарьсан бүх чадал баланс зангилаанд хүрнэ.", "h": "Тайлбар: 5-р зангилааны ачааллыг 10 МВт нэмэгдүүлбэл (k = 5-д −0.1 о.н. тарилт) 1–2 шугамын урсгал 0.786·10 = 7.9 МВт, 2–5 шугамынх 7.0 МВт өснө. Багана бүрийн 1–2 ба 1–3 мөрийн нийлбэр −1 — тарьсан бүх чадал баланс зангилаанд хүрнэ.", "x": "ex"}, {"t": "p", "s": "1–2 шугам тасрах (n−1): PTDF12,(1→2) = 0.843, LODF ба шинэ урсгал:", "h": "<b>1–2 шугам тасрах </b>(n−1): PTDF<sub>12,(1→2)</sub> = 0.843, LODF ба шинэ урсгал:", "x": "ex"}, {"t": "tbl", "s": "", "head": ["Салаа", "1–3", "2–3", "2–4", "2–5", "3–4", "4–5"], "rows": [["LODF", "1.000", "−0.455", "−0.364", "−0.182", "0.545", "0.182"], ["Өмнө, МВт", "39.6", "24.3", "27.4", "53.7", "18.9", "6.3"], ["Дараа, МВт", "125.0", "−14.5", "−3.6", "38.2", "65.5", "21.8"]]}, {"t": "cap", "s": "Хүснэгт 11.7. 1–2 шугам тасрах үеийн урсгал", "h": "Хүснэгт 11.7. 1–2 шугам тасрах үеийн урсгал"}, {"t": "p", "s": "1-р зангилаа зөвхөн 1–2 ба 1–3 шугамаар холбогдсон тул бүх 125 МВт 1–3 шугамаар явна (LODF = 1); 2–3, 2–4 шугамын урсгалын чиглэл эсрэг болно; 3–4 шугам 3.5 дахин ачаалагдана. 1–3 шугамын дулааны хязгаар 125 МВт-аас бага бол энэ горим зөвшөөрөгдөхгүй — n−1 шалгуур хангагдахгүй.", "h": "1-р зангилаа зөвхөн 1–2 ба 1–3 шугамаар холбогдсон тул бүх 125 МВт 1–3 шугамаар явна (LODF = 1); 2–3, 2–4 шугамын урсгалын чиглэл эсрэг болно; 3–4 шугам 3.5 дахин ачаалагдана. 1–3 шугамын дулааны хязгаар 125 МВт-аас бага бол энэ горим зөвшөөрөгдөхгүй — n−1 шалгуур хангагдахгүй.", "x": "ex"}, {"t": "h", "l": 2, "s": "n−1 шинжилгээ", "h": "<b>n−1 шинжилгээ</b>"}, {"t": "p", "s": "Элемент бүрийг ээлжлэн «тасалж» горимыг тооцох нь n−1 шинжилгээ. Мянга мянган хувилбартай тул эхлээд DC/LODF-оор хурдан «шүүж», аюултай хувилбаруудыг л AC (Ньютон эсвэл хурдан задалсан) аргаар нарийвчилна. 5 зангилааны схемийн бүх шугамын тасралтын DC үр дүн:", "h": "Элемент бүрийг ээлжлэн «тасалж» горимыг тооцох нь n−1 шинжилгээ. Мянга мянган хувилбартай тул эхлээд DC/LODF-оор хурдан «шүүж», аюултай хувилбаруудыг л AC (Ньютон эсвэл хурдан задалсан) аргаар нарийвчилна. 5 зангилааны схемийн бүх шугамын тасралтын DC үр дүн:"}, {"t": "tbl", "s": "", "head": ["Тасарсан шугам", "1–2", "1–3", "2–3", "2–4", "2–5", "3–4", "4–5"], "rows": [["Хамгийн их ачаалалтай шугам", "1–3", "1–2", "1–2", "1–2", "1–2", "1–2", "1–2"], ["Түүний урсгал, МВт", "125.0", "125.0", "77.3", "78.1", "74.2", "92.5", "86.7"], ["Онцлох өөрчлөлт", "3–4: 65.5", "2–5: 60.9", "2–4: 38.2", "2–5: 61.5", "4–5: 60.0", "2–5: 60.0", "2–5: 60.0"]]}, {"t": "cap", "s": "Хүснэгт 11.8. n−1 шинжилгээ (DC загвар)", "h": "Хүснэгт 11.8. n−1 шинжилгээ (DC загвар)"}, {"t": "p", "s": "Хамгийн хүнд хоёр хувилбар нь баланс зангилаанаас гарах хоёр шугамын аль нэг тасрах (үлдсэн шугам 125 МВт дамжуулна). 2–5 шугам тасрахад 5-р зангилааны 60 МВт бүхэлдээ 4–5 шугамаар (урсгал 6.3 → 60.0 МВт) ирнэ. Шугамуудын зөвшөөрөгдөх чадлыг мэдэж, n−1 шалгуурыг хангах эсэхийг шийднэ.", "h": "Хамгийн хүнд хоёр хувилбар нь баланс зангилаанаас гарах хоёр шугамын аль нэг тасрах (үлдсэн шугам 125 МВт дамжуулна). 2–5 шугам тасрахад 5-р зангилааны 60 МВт бүхэлдээ 4–5 шугамаар (урсгал 6.3 → 60.0 МВт) ирнэ. Шугамуудын зөвшөөрөгдөх чадлыг мэдэж, n−1 шалгуурыг хангах эсэхийг шийднэ."}, {"t": "h", "l": 1, "s": "6. Горимын хязгаар", "h": "<b>6. Горимын хязгаар</b>"}, {"t": "p", "s": "Тогтсон горимын тооцооны зорилго нь горимыг тооцоод зогсохгүй, түүнийг зөвшөөрөгдөх эсэхийг шалгах явдал. Үндсэн хязгаарууд:", "h": "Тогтсон горимын тооцооны зорилго нь горимыг тооцоод зогсохгүй, түүнийг <b>зөвшөөрөгдөх </b>эсэхийг шалгах явдал. Үндсэн хязгаарууд:"}, {"t": "tbl", "s": "", "head": ["Хязгаар", "Шалтгаан", "Шалгах хэмжигдэхүүн"], "rows": [["Дулааны", "Дамжуулагчийн халалт, унжилт (лекц 2), трансформаторын халалт", "I ≤ I , S ≤ S зөвш н"], ["Хүчдэлийн", "Хэрэглэгчийн хүчдэлийн чанар, тусгаарлагч", "0.95–1.05 (1.1) U н"], ["Генераторын", "Хүчин чадлын диаграмм (лекц 4)", "P, Q ≤ Q ≤ Q min max"], ["Статик тогтворжилт (өнцгийн)", "Синхрон машинуудын синхронизм", "δ ≤ 30–40°, нөөц ≥ 20 %"], ["Хүчдэлийн тогтворжилт", "Ачааллын шугаман бус хамаарал, хуурмаг чадлын дутагдал", "λ , нөөц ≥ 8–15 % max"]]}, {"t": "cap", "s": "Хүснэгт 11.9. Горимын хязгаарууд", "h": "Хүснэгт 11.9. Горимын хязгаарууд"}, {"t": "p", "s": "Статик (өнцгийн) тогтворжилт. Хоёр системийн хооронд P = U1U2sinδ/X (6.13) дамжуулах чадлын дээд хязгаар δ = 90°-д Pmax = U1U2/X. Бага зэргийн цочролд тогтворжилтыг хадгалах үүднээс хэвийн горимд статик тогтворжилтын нөөц KP = (Pmax − P)/P·100 % ≥ 20 % (ослын дараах горимд ≥ 8 %) байхыг шаарддаг. Лекц 6-ийн жишээнд (220 кВ, 200 км, Pmax = 576 МВт) 150 МВт дамжуулахад нөөц 284 %.", "h": "<b>Статик (өнцгийн) тогтворжилт. </b>Хоёр системийн хооронд P = U<sub>1</sub>U<sub>2</sub>sinδ/X (6.13) дамжуулах чадлын дээд хязгаар δ = 90°-д P<sub>max</sub> = U<sub>1</sub>U<sub>2</sub>/X. Бага зэргийн цочролд тогтворжилтыг хадгалах үүднээс хэвийн горимд <b>статик тогтворжилтын нөөц </b>K<sub>P</sub> = (P<sub>max</sub> − P)/P·100 % ≥ 20 % (ослын дараах горимд ≥ 8 %) байхыг шаарддаг. Лекц 6-ийн жишээнд (220 кВ, 200 км, P<sub>max</sub> = 576 МВт) 150 МВт дамжуулахад нөөц 284 %."}, {"t": "p", "s": "Жишээ 11.5. Горимыг хязгаартай тулгах. 5 зангилааны схемийг 110 кВ сүлжээ гэж үзье: 1–2 ба 2–5 шугам АС-240 (Iзөвш = 610 А), бусад нь АС-185 (510 А). Хэвийн горимын (Хүснэгт 9.5) гүйдэл I = S/(√3U):", "h": "<b>Жишээ 11.5. Горимыг хязгаартай тулгах. </b>5 зангилааны схемийг 110 кВ сүлжээ гэж үзье: 1–2 ба 2–5 шугам АС-240 (I<sub>зөвш</sub> = 610 А), бусад нь АС-185 (510 А). Хэвийн горимын (Хүснэгт 9.5) гүйдэл I = S/(√3U):", "x": "ex"}, {"t": "tbl", "s": "", "head": ["Шугам", "1–2", "1–3", "2–3", "2–4", "2–5", "3–4", "4–5"], "rows": [["S, МВА", "89.3", "40.7", "24.9", "28.1", "55.3", "19.6", "6.7"], ["I, А", "442", "202", "125", "141", "277", "100", "34"], ["Ачаалал, %", "72", "40", "25", "28", "45", "20", "7"]]}, {"t": "cap", "s": "Хүснэгт 11.10. Шугамын ачаалал (хэвийн горим)", "h": "Хүснэгт 11.10. Шугамын ачаалал (хэвийн горим)"}, {"t": "p", "s": "Хэвийн горимд бүх хязгаар хангагдана: хүчдэл 1.018–1.060, хамгийн их ачаалал 72 %. Харин 1–2 шугам тасрахад (Хүснэгт 11.7) 1–3 шугамаар 125 МВт буюу ~650 А (хүчдэл 0.95 орчим гэвэл) гүйж, АС-185-ын 510 А-ийг 27 %-иар хэтрүүлнэ — n−1 шалгуур хангагдахгүй. Арга хэмжээ: 1–3 шугамыг АС-240 болгох, 2-р зангилааны генерацийг нэмэгдүүлэх (PTDF: 2-р зангилаанд 1 МВт нэмэхэд 1–3-ын ачаалал 0.157 МВт буурна) эсвэл ослын автоматаар ачаалал хязгаарлах.", "h": "Хэвийн горимд бүх хязгаар хангагдана: хүчдэл 1.018–1.060, хамгийн их ачаалал 72 %. Харин 1–2 шугам тасрахад (Хүснэгт 11.7) 1–3 шугамаар 125 МВт буюу ~650 А (хүчдэл 0.95 орчим гэвэл) гүйж, АС-185-ын 510 А-ийг 27 %-иар хэтрүүлнэ — <b>n−1 шалгуур</b> <b>хангагдахгүй</b>. Арга хэмжээ: 1–3 шугамыг АС-240 болгох, 2-р зангилааны генерацийг нэмэгдүүлэх (PTDF: 2-р зангилаанд 1 МВт нэмэхэд 1–3-ын ачаалал 0.157 МВт буурна) эсвэл ослын автоматаар ачаалал хязгаарлах.", "x": "ex"}, {"t": "h", "l": 1, "s": "7. P–V муруй ба хүчдэлийн тогтворжилт", "h": "<b>7. P–V муруй ба хүчдэлийн тогтворжилт</b>"}, {"t": "p", "s": "Ачааллыг λ коэффициентоор өсгөж (P = λP0, Q = λQ0) тогтсон горимыг дараалан тооцоход зангилааны хүчдэлийн λ-аас хамаарах муруйг P–V муруй («хамрын муруй») гэнэ. Муруй дээд (тогтвортой) ба доод (тогтворгүй) салаатай бөгөөд тэдгээр нь λmax цэгт («хамар») нийлнэ. λ > λmax үед тогтсон горим байхгүй. Хамрын цэгт Якобиан сингуляр (det J = 0, лекц 10, Хүснэгт 10.6). λmax − 1-ийг ачааллын нөөц гэнэ.", "h": "Ачааллыг λ коэффициентоор өсгөж (<b>P </b>= λ<b>P</b><sub>0</sub>, <b>Q </b>= λ<b>Q</b><sub>0</sub>) тогтсон горимыг дараалан тооцоход зангилааны хүчдэлийн λ-аас хамаарах муруйг <b>P–V муруй </b>(«хамрын муруй») гэнэ. Муруй дээд (тогтвортой) ба доод (тогтворгүй) салаатай бөгөөд тэдгээр нь <b>λ</b><sub>max</sub> цэгт («хамар») нийлнэ. λ &gt; λ<sub>max</sub> үед тогтсон горим байхгүй. Хамрын цэгт Якобиан сингуляр (det <b>J </b>= 0, лекц 10, Хүснэгт 10.6). λ<sub>max</sub> − 1-ийг <b>ачааллын нөөц </b>гэнэ."}, {"t": "p", "s": "U₂ 1.0 хэвийн горим (λ = 1)", "h": "<sup>U₂</sup> 1<sub>.0</sub> <sup>хэвийн</sup> <sup>горим</sup> <sup>(λ</sup> <sup>=</sup> <sup>1)</sup>"}, {"t": "tbl", "s": "", "head": ["", "", "", ""], "rows": [["", "", "", ""], ["", "", "λmax = 3. тогтворгүй салаа", "55"], ["", "", "нөөц", ""], ["", "", "", ""]]}, {"t": "p", "s": "0.8", "h": "0<sub>.8</sub>"}, {"t": "p", "s": "0.6", "h": "0<sub>.6</sub>"}, {"t": "p", "s": "0.4", "h": "0<sub>.4</sub>"}, {"t": "p", "s": "0.20 1 2 3 4", "h": "<sup>0.2</sup>0 <sub>1</sub> <sub>2</sub> <sub>3</sub> <sub>4</sub>"}, {"t": "p", "s": "Ачааллын коэффициент λ", "h": "А<sub>чааллын</sub> <sub>коэффициент</sub> <sub>λ</sub>"}, {"t": "cap", "s": "Зураг 11.1. Стендийн 3 зангилааны схемийн 2-р зангилааны P–V муруй", "h": "Зураг 11.1. Стендийн 3 зангилааны схемийн 2-р зангилааны P–V муруй"}, {"t": "p", "s": "Жишээ 11.6. Стендийн 3 зангилааны схемийн 2-р зангилааны ачааллыг (400 + j250 МВА) λ-аар өсгөсөн (3-р генераторын P тогтмол, Q хязгааргүй). Дээд салааг λ-аар, хамрын орчим ба доод салааг U2-оор параметрчилж (үргэлжлүүлэлтийн арга) тооцов:", "h": "<b>Жишээ 11.6. </b>Стендийн 3 зангилааны схемийн 2-р зангилааны ачааллыг (400 + j250 МВА) λ-аар өсгөсөн (3-р генераторын P тогтмол, Q хязгааргүй). Дээд салааг λ-аар, хамрын орчим ба доод салааг U<sub>2</sub>-оор параметрчилж (үргэлжлүүлэлтийн арга) тооцов:", "x": "ex"}, {"t": "tbl", "s": "", "head": ["λ", "0", "0.5", "1.0", "1.5", "2.0", "2.5", "3.0", "3.25", "3.5", "3.548"], "rows": [["U (дээд) 2", "1.044", "1.009", "0.972", "0.930", "0.882", "0.824", "0.749", "0.697", "0.609", "0.548"], ["U (доод) 2", "", "", "", "", "", "≈0.26", "≈0.34", "≈0.39", "≈0.49", "0.548"]]}, {"t": "cap", "s": "Хүснэгт 11.11. P–V муруйн цэгүүд", "h": "Хүснэгт 11.11. P–V муруйн цэгүүд"}, {"t": "p", "s": "λmax = 3.548 (1419 МВт), хамрын цэгийн хүчдэл 0.548 о.н. — хэвийн горимын ачааллын нөөц 255 %. Хүчдэл 0.9 о.н. хүрэх ачаалал λ ≈ 1.8 буюу хүчдэлийн хязгаар тогтворжилтын хязгаараас хамаагүй эрт хүрнэ. Энэ нь хүчтэй (бага эсэргүүцэлтэй) сүлжээний онцлог; урт шугамаар тэжээгдэх алслагдсан бүсэд хамрын цэг 0.8–0.9 о.н.-д байж, хүчдэл «хэвийн» харагдаж байхад нурах аюултай.", "h": "λ<sub>max</sub> = 3.548 (1419 МВт), хамрын цэгийн хүчдэл 0.548 о.н. — хэвийн горимын ачааллын нөөц 255 %. Хүчдэл 0.9 о.н. хүрэх ачаалал λ ≈ 1.8 буюу хүчдэлийн хязгаар тогтворжилтын хязгаараас хамаагүй эрт хүрнэ. Энэ нь хүчтэй (бага эсэргүүцэлтэй) сүлжээний онцлог; урт шугамаар тэжээгдэх алслагдсан бүсэд хамрын цэг 0.8–0.9 о.н.-д байж, хүчдэл «хэвийн» харагдаж байхад нурах аюултай.", "x": "ex"}, {"t": "p", "s": "Жишээ 11.7. 5 зангилааны схемийн ачааллын хязгаар (Лабораторийн ажил 7). Бүх ачааллыг λ-аар өсгөж, 2-р зангилааны генерацийг (40 + j30) тогтмол байлгав (нэмэгдлийг баланс авна — стендийн нөхцөл):", "h": "<b>Жишээ 11.7. 5 зангилааны схемийн ачааллын хязгаар </b>(Лабораторийн ажил 7). Бүх ачааллыг λ-аар өсгөж, 2-р зангилааны генерацийг (40 + j30) тогтмол байлгав (нэмэгдлийг баланс авна — стендийн нөхцөл):", "x": "ex"}, {"t": "tbl", "s": "", "head": ["λ", "1.0", "1.5", "2.0", "2.5", "2.8", "3.0", "3.035"], "rows": [["U 2", "1.047", "1.019", "0.983", "0.934", "0.889", "0.835", "0.802"], ["U 3", "1.024", "0.982", "0.930", "0.859", "0.796", "0.719", "0.673"], ["U 4", "1.024", "0.980", "0.926", "0.852", "0.787", "0.707", "0.659"], ["U 5", "1.018", "0.969", "0.907", "0.824", "0.748", "0.651", "0.590"], ["НР давталт", "4", "4", "4", "5", "6", "7", "—"]]}, {"t": "cap", "s": "Хүснэгт 11.12. 5 зангилааны схемийн V(λ)", "h": "Хүснэгт 11.12. 5 зангилааны схемийн V(λ)"}, {"t": "p", "s": "λmax ≈ 3.04. Хамгийн сул зангилаа — 5 (хүчдэл хамгийн бага, хамгийн хурдан буурна, dU/dλ хамгийн их): баланс зангилаанаас хамгийн хол, ачаалал хамгийн их (60 МВт), зөвхөн 2–5 ба 4–5 шугамаар тэжээгдэнэ. 0.95 о.н. хязгаарт 5-р зангилаа λ ≈ 1.65-д хүрнэ. Хуурмаг чадлын эх үүсвэрийг (конденсатор, СТК) хамгийн сул зангилаанд байрлуулах нь хамгийн үр дүнтэй (лекц 12).", "h": "λ<sub>max</sub> ≈ 3.04. Хамгийн сул зангилаа — <b>5 </b>(хүчдэл хамгийн бага, хамгийн хурдан буурна, dU/dλ хамгийн их): баланс зангилаанаас хамгийн хол, ачаалал хамгийн их (60 МВт), зөвхөн 2–5 ба 4–5 шугамаар тэжээгдэнэ. 0.95 о.н. хязгаарт 5-р зангилаа λ ≈ 1.65-д хүрнэ. Хуурмаг чадлын эх үүсвэрийг (конденсатор, СТК) хамгийн сул зангилаанд байрлуулах нь хамгийн үр дүнтэй (лекц 12).", "x": "ex"}, {"t": "h", "l": 1, "s": "8. Хүчдэлийн тогтворжилтын шинжүүр", "h": "<b>8. Хүчдэлийн тогтворжилтын шинжүүр</b>"}, {"t": "h", "l": 2, "s": "Q–V муруй ба хуурмаг чадлын нөөц", "h": "<b>Q–V муруй ба хуурмаг чадлын нөөц</b>"}, {"t": "p", "s": "Зангилааны хүчдэлийг дураар тогтоож (зангилааг «зохиомол PV» болгож), түүнийг барихад шаардлагатай хуурмаг чадлыг тооцвол Q–V муруй гарна. Муруйн хамгийн бага цэг ба Q = 0 шугамын хоорондох зай нь тухайн зангилааны хуурмаг чадлын нөөц — зангилаанд нэмж болох хуурмаг ачааллын хэмжээ.", "h": "Зангилааны хүчдэлийг дураар тогтоож (зангилааг «зохиомол PV» болгож), түүнийг барихад шаардлагатай хуурмаг чадлыг тооцвол <b>Q–V муруй </b>гарна. Муруйн хамгийн бага цэг ба Q = 0 шугамын хоорондох зай нь тухайн зангилааны <b>хуурмаг чадлын нөөц </b>— зангилаанд нэмж болох хуурмаг ачааллын хэмжээ."}, {"t": "p", "s": "Жишээ 11.8. 5 зангилааны схемийн 5-р зангилааны Q–V муруй (бусад өгөгдөл хэвийн):", "h": "<b>Жишээ 11.8. </b>5 зангилааны схемийн 5-р зангилааны Q–V муруй (бусад өгөгдөл хэвийн):", "x": "ex"}, {"t": "tbl", "s": "", "head": ["U , о.н. 5", "1.10", "1.05", "1.00", "0.90", "0.80", "0.70", "0.60", "0.55", "0.50"], "rows": [["Шаардлагатай Q, Мвар", "67.1", "24.9", "−13.2", "−77.5", "−126.1", "−159.2", "−177.1", "−180.3", "−179.8"]]}, {"t": "cap", "s": "Хүснэгт 11.13. Q–V муруйн цэгүүд", "h": "Хүснэгт 11.13. Q–V муруйн цэгүүд"}, {"t": "p", "s": "Хэвийн горимд (Q = 0) U5 = 1.018. Хүчдэлийг 1.05 болгоход 24.9 Мвар, 1.10 болгоход 67.1 Мвар хуурмаг чадал хэрэгтэй — хүчдэлийн мэдрэмж dU/dQ ≈ 0.0013 о.н./Мвар (ойролцоогоор 1 Мвар-д 0.13 %). Муруйн минимум U ≈ 0.53-д −180 Мвар: 5-р зангилаанд нэмэлт 180 Мвар хуурмаг ачаалал залгахад хүчдэл нурна — хуурмаг чадлын нөөц ≈ 180 Мвар. Минимумаас доош (dQ/dU < 0) муж тогтворгүй.", "h": "Хэвийн горимд (Q = 0) U<sub>5</sub> = 1.018. Хүчдэлийг 1.05 болгоход 24.9 Мвар, 1.10 болгоход 67.1 Мвар хуурмаг чадал хэрэгтэй — хүчдэлийн мэдрэмж dU/dQ ≈ 0.0013 о.н./Мвар (ойролцоогоор 1 Мвар-д 0.13 %). Муруйн минимум U ≈ 0.53-д −180 Мвар: 5-р зангилаанд нэмэлт 180 Мвар хуурмаг ачаалал залгахад хүчдэл нурна — <b>хуурмаг чадлын</b> <b>нөөц ≈ 180 Мвар</b>. Минимумаас доош (dQ/dU &lt; 0) муж тогтворгүй.", "x": "ex"}, {"t": "p", "s": "Мэдрэмжийн шинжүүр. Якобианы L блокоос (эсвэл бүрэн Якобианаас H-г хасч бууруулсан JR = L − MH⁻¹N) ΔU = JR⁻¹ΔQ — зангилааны хуурмаг чадлын өөрчлөлт хүчдэлд хэрхэн нөлөөлөхийг заана. dUi/dQi > 0 бол горим тогтвортой; хязгаарт ойртоход тэр нь огцом өсч, хамарт ∞, доод салаанд сөрөг болно. Модаль шинжилгээ: JR-ийн хамгийн бага хувийн утга тэг рүү ойртох хурд нь хязгаар хүртэлх зайг, хувийн вектор нь хамгийн сул зангилааг заана.", "h": "<b>Мэдрэмжийн шинжүүр. </b>Якобианы <b>L </b>блокоос (эсвэл бүрэн Якобианаас <b>H</b>-г хасч бууруулсан <b>J</b><sub>R</sub> = <b>L </b>− <b>MH</b>⁻¹<b>N</b>) Δ<b>U </b>= <b>J</b><sub>R</sub>⁻¹Δ<b>Q </b>— зангилааны хуурмаг чадлын өөрчлөлт хүчдэлд хэрхэн нөлөөлөхийг заана. dU<sub>i</sub>/dQ<sub>i</sub> &gt; 0 бол горим тогтвортой; хязгаарт ойртоход тэр нь огцом өсч, хамарт ∞, доод салаанд сөрөг болно. <b>Модаль шинжилгээ</b>: <b>J</b><sub>R</sub>-ийн хамгийн бага хувийн утга тэг рүү ойртох хурд нь хязгаар хүртэлх зайг, хувийн вектор нь хамгийн сул зангилааг заана.", "x": "ex"}, {"t": "p", "s": "Үргэлжлүүлэлтийн арга (continuation power flow). Хамрын цэгийн ойролцоо Якобиан сингуляр болох тул энгийн Ньютон-Рафсон нийлэхгүй. Үргэлжлүүлэлтийн арга нь λ-г нэмэлт үл мэдэгдэгч болгож, (1) таамаглал — шүргэгч вектороор дараагийн цэгийг урьдчилан тооцох; (2) засвар — λ эсвэл аль нэг хүчдэлийг тогтмол байлгаж (параметрчлэл) Ньютоны аргаар засах. Хамрын ойролцоо параметрийг λ-аас U-д шилжүүлснээр муруйг бүтнээр нь (доод салааг оруулаад) байгуулна — Жишээ 11.6-д ийм аргаар доод салааг олсон.", "h": "<b>Үргэлжлүүлэлтийн арга </b>(continuation power flow). Хамрын цэгийн ойролцоо Якобиан сингуляр болох тул энгийн Ньютон-Рафсон нийлэхгүй. Үргэлжлүүлэлтийн арга нь λ-г нэмэлт үл мэдэгдэгч болгож, (1) <b>таамаглал </b>— шүргэгч вектороор дараагийн цэгийг урьдчилан тооцох; (2) <b>засвар </b>— λ эсвэл аль нэг хүчдэлийг тогтмол байлгаж (параметрчлэл) Ньютоны аргаар засах. Хамрын ойролцоо параметрийг λ-аас U-д шилжүүлснээр муруйг бүтнээр нь (доод салааг оруулаад) байгуулна — Жишээ 11.6-д ийм аргаар доод салааг олсон.", "x": "ex"}, {"t": "p", "s": "Практик ач холбогдол. Дэлхийн томоохон системийн нуралтын (1978 Франц, 1987 Токио, 2003 АНУ-Канад) нэг гол шалтгаан нь хүчдэлийн тогтворжилт алдагдсан явдал. Иймд диспетчерийн төвүүд бодит цагт λmax-ыг тооцож, нөөц 8–15 %-иас бага болбол хуурмаг чадлын нөөц ашиглах, ачаалал хязгаарлах арга хэмжээ авдаг.", "h": "<b>Практик ач холбогдол. </b>Дэлхийн томоохон системийн нуралтын (1978 Франц, 1987 Токио, 2003 АНУ-Канад) нэг гол шалтгаан нь хүчдэлийн тогтворжилт алдагдсан явдал. Иймд диспетчерийн төвүүд бодит цагт λ<sub>max</sub>-ыг тооцож, нөөц 8–15 %-иас бага болбол хуурмаг чадлын нөөц ашиглах, ачаалал хязгаарлах арга хэмжээ авдаг.", "x": "ex"}, {"t": "h", "l": 1, "s": "9. Лабораторийн стендтэй холбоо", "h": "<b>9. Лабораторийн стендтэй холбоо</b>"}, {"t": "p", "s": "Стенд дээр шалгах (лекц 11). Лабораторийн ажил 7 «Ачааллын хязгаар»: «5 зангилаа» схем, «7. Ачааллын судалгаа» хуудас, алхам 0.1-ээр V(λ) муруйг байгуулж хамгийн сул зангилааг тодорхойл; Хүснэгт 11.12-тэй тулга (стендийн λmax нь НьютонРафсон нийлсэн сүүлчийн утга тул алхмаас хамаарч 3.0 орчим гарна). Дээд самбарын λг 2.9, 3.0, 3.03 болгож F7-оор давталтын тоо хэрхэн өсөхийг ажиглаж, Якобиан бөхрөхтэй холбон тайлбарла. Мөн «3 зангилаа» схемд λmax ≈ 3.55 гарахыг шалга. Хурдан задалсан ба DC загварыг Python-д програмчилж Хүснэгт 11.1, 11.5-ыг давт.", "h": "<b>Стенд дээр шалгах (лекц 11). Лабораторийн ажил 7 «Ачааллын хязгаар»: </b>«5 зангилаа» схем, «7. Ачааллын судалгаа» хуудас, алхам 0.1-ээр V(λ) муруйг байгуулж хамгийн сул зангилааг тодорхойл; Хүснэгт 11.12-тэй тулга (стендийн λ<sub>max</sub> нь НьютонРафсон нийлсэн сүүлчийн утга тул алхмаас хамаарч 3.0 орчим гарна). Дээд самбарын λг 2.9, 3.0, 3.03 болгож F7-оор давталтын тоо хэрхэн өсөхийг ажиглаж, Якобиан бөхрөхтэй холбон тайлбарла. Мөн «3 зангилаа» схемд λ<sub>max</sub> ≈ 3.55 гарахыг шалга. Хурдан задалсан ба DC загварыг Python-д програмчилж Хүснэгт 11.1, 11.5-ыг давт."}, {"t": "h", "l": 1, "s": "Дүгнэлт", "h": "<b>Дүгнэлт</b>"}, {"t": "p", "s": "X ≫ R үед P–θ ба Q–U холбоо давамгай тул Якобианыг задалж болно.", "h": "X ≫ R үед P–θ ба Q–U холбоо давамгай тул Якобианыг задалж болно."}, {"t": "p", "s": "Хурдан задалсан арга: ΔP/U = B′Δθ, ΔQ/U = B″ΔU; тогтмол матриц, нэг удаа задлана; шийдэл нарийн, давталт 2 дахин их ч нийт хугацаа бага; R/X их үед муудна.", "h": "Хурдан задалсан арга: Δ<b>P</b>/<b>U </b>= <b>B</b>′Δθ, Δ<b>Q</b>/<b>U </b>= <b>B</b>″Δ<b>U</b>; тогтмол матриц, нэг удаа задлана; шийдэл нарийн, давталт 2 дахин их ч нийт хугацаа бага; R/X их үед муудна."}, {"t": "p", "s": "DC загвар: P = B′θ — шугаман, давталтгүй, бодит урсгалын алдаа хэдэн хувь; хүчдэлийн мэдээлэлгүй.", "h": "DC загвар: <b>P </b>= <b>B</b>′θ — шугаман, давталтгүй, бодит урсгалын алдаа хэдэн хувь; хүчдэлийн мэдээлэлгүй."}, {"t": "p", "s": "PTDF ба LODF нь n−1 шинжилгээг хурдан хийх боломж олгоно.", "h": "PTDF ба LODF нь n−1 шинжилгээг хурдан хийх боломж олгоно."}, {"t": "p", "s": "Горимын хязгаар: дулааны, хүчдэлийн, генераторын, статик ба хүчдэлийн тогтворжилт.", "h": "Горимын хязгаар: дулааны, хүчдэлийн, генераторын, статик ба хүчдэлийн тогтворжилт."}, {"t": "p", "s": "P–V муруй, λmax, хамрын цэгт det J = 0; үргэлжлүүлэлтийн арга.", "h": "P–V муруй, λ<sub>max</sub>, хамрын цэгт det <b>J </b>= 0; үргэлжлүүлэлтийн арга."}, {"t": "p", "s": "Q–V муруй нь зангилааны хуурмаг чадлын нөөцийг (5 зангилааны схемийн 5-р зангилаанд ≈180 Мвар) тодорхойлно; хамгийн сул зангилаанд компенсаци байрлуулна.", "h": "Q–V муруй нь зангилааны хуурмаг чадлын нөөцийг (5 зангилааны схемийн 5-р зангилаанд ≈180 Мвар) тодорхойлно; хамгийн сул зангилаанд компенсаци байрлуулна."}, {"t": "h", "l": 1, "s": "Хяналтын асуулт", "h": "<b>Хяналтын асуулт</b>"}, {"t": "p", "s": "1. Якобианыг задлах физик үндэслэл юу вэ?", "h": "1. Якобианыг задлах физик үндэслэл юу вэ?"}, {"t": "p", "s": "2. Хурдан задалсан аргын гурван таамаглал.", "h": "2. Хурдан задалсан аргын гурван таамаглал."}, {"t": "p", "s": "3. B′ ба B″ матрицад ямар элементүүд орох вэ? Яагаад ялгаатай вэ?", "h": "3. <b>B</b>′ ба <b>B</b>″ матрицад ямар элементүүд орох вэ? Яагаад ялгаатай вэ?"}, {"t": "p", "s": "4. Хурдан задалсан аргын шийдэл яагаад Ньютон-Рафсоных шиг нарийвчлалтай вэ?", "h": "4. Хурдан задалсан аргын шийдэл яагаад Ньютон-Рафсоных шиг нарийвчлалтай вэ?"}, {"t": "p", "s": "5. DC загварын таамаглал, давуу ба сул тал.", "h": "5. DC загварын таамаглал, давуу ба сул тал."}, {"t": "p", "s": "6. PTDF ба LODF-ийн тодорхойлолт, хэрэглээ.", "h": "6. PTDF ба LODF-ийн тодорхойлолт, хэрэглээ."}, {"t": "p", "s": "7. Горимын үндсэн хязгааруудыг нэрлэ.", "h": "7. Горимын үндсэн хязгааруудыг нэрлэ."}, {"t": "p", "s": "8. Статик тогтворжилтын нөөцийн томьёо ба нормын утга.", "h": "8. Статик тогтворжилтын нөөцийн томьёо ба нормын утга."}, {"t": "p", "s": "9. P–V муруй, хамрын цэг, ачааллын нөөц.", "h": "9. P–V муруй, хамрын цэг, ачааллын нөөц."}, {"t": "p", "s": "10. Хамрын цэгийн ойролцоо Ньютон-Рафсоны арга яагаад нийлэхгүй вэ?", "h": "10. Хамрын цэгийн ойролцоо Ньютон-Рафсоны арга яагаад нийлэхгүй вэ?"}, {"t": "p", "s": "Үргэлжлүүлэлтийн арга.", "h": "Үргэлжлүүлэлтийн арга."}, {"t": "h", "l": 1, "s": "Бие даалтын даалгавар", "h": "<b>Бие даалтын даалгавар</b>"}, {"t": "p", "s": "1. Жишээ 11.1-ийн эхний давталтыг гараар хий: ΔP/U-ээс B′-ээр Δθ, дараа нь ΔQ2/U2оос B″-ээр ΔU2.", "h": "1. Жишээ 11.1-ийн эхний давталтыг гараар хий: Δ<b>P</b>/<b>U</b>-ээс <b>B</b>′-ээр Δθ, дараа нь ΔQ<sub>2</sub>/U<sub>2</sub>оос <b>B</b>″-ээр ΔU<sub>2</sub>."}, {"t": "p", "s": "2. Хүснэгт 11.6-г ашиглаж 3-р зангилааны ачааллыг 20 МВт нэмэхэд шугамын урсгалыг тооцоод DC загварыг дахин бодож шалга.", "h": "2. Хүснэгт 11.6-г ашиглаж 3-р зангилааны ачааллыг 20 МВт нэмэхэд шугамын урсгалыг тооцоод DC загварыг дахин бодож шалга."}, {"t": "p", "s": "3. Хүснэгт 11.7-ийн LODF-ийг 2–5 шугам тасрах тохиолдолд тооцож Хүснэгт 11.8-ын 2–5 баганатай тулга.", "h": "3. Хүснэгт 11.7-ийн LODF-ийг 2–5 шугам тасрах тохиолдолд тооцож Хүснэгт 11.8-ын 2–5 баганатай тулга."}, {"t": "p", "s": "4. Q–V муруйг (Жишээ 11.8) 3-р зангилааны хувьд байгуулж хуурмаг чадлын нөөцийг 5-р зангилаанхтай харьцуул.", "h": "4. Q–V муруйг (Жишээ 11.8) 3-р зангилааны хувьд байгуулж хуурмаг чадлын нөөцийг 5-р зангилаанхтай харьцуул."}, {"t": "p", "s": "5. Жишээ 11.7-д 5-р зангилаанд 20 Мвар конденсатор залгаж λmax хэрхэн өөрчлөгдөхийг Python эсвэл стендээр тодорхойл.", "h": "5. Жишээ 11.7-д 5-р зангилаанд 20 Мвар конденсатор залгаж λ<sub>max</sub> хэрхэн өөрчлөгдөхийг Python эсвэл стендээр тодорхойл."}, {"t": "h", "l": 1, "s": "Ашигласан ном", "h": "<b>Ашигласан ном</b>"}, {"t": "p", "s": "1. Ш.Гантөмөр. Цахилгаан шугам сүлжээ, систем. — УБ.: Соёмбопринтинг, 2017.", "h": "1. Ш.Гантөмөр. Цахилгаан шугам сүлжээ, систем. — УБ.: Соёмбопринтинг, 2017."}, {"t": "p", "s": "2. Stott B.,Alsac O. Fast decoupled load flow. IEEE Trans. PAS, 1974.", "h": "2. Stott B.,Alsac O. Fast decoupled load flow. IEEE Trans. PAS, 1974."}, {"t": "p", "s": "3. Kundur P. Power System Stability and Control. — McGraw-Hill, 1994.", "h": "3. Kundur P. Power System Stability and Control. — McGraw-Hill, 1994."}, {"t": "p", "s": "4. Ш.Гантөмөр, Ч.Зундуйсүрэн. Эрчим хүчний системийн горимын оновчлол. — УБ., 2001.", "h": "4. Ш.Гантөмөр, Ч.Зундуйсүрэн. Эрчим хүчний системийн горимын оновчлол. — УБ., 2001."}, {"t": "p", "s": "5. WoodA.J., Wollenberg B.F. Power Generation, Operation and Control. — Wiley, 2014.", "h": "5. WoodA.J., Wollenberg B.F. Power Generation, Operation and Control. — Wiley, 2014."}];